package com.realstant.nativegame; import android.content.*; public final class SaveManager { private final SharedPreferences p; public SaveManager(Context c){p=c.getSharedPreferences("realstant",Context.MODE_PRIVATE);} public void save(GameState s){p.edit().putString("track",s.track).putString("vehicle",s.vehicle).putInt("money",s.money).apply();} public void load(GameState s){s.track=p.getString("track","green_valley");s.vehicle=p.getString("vehicle","vortex");s.money=p.getInt("money",12500);} }
